(window.TNQ=window.TNQ||[]).push({"terms":{"순환적 인과관계":{"d":"원인과 결과가 일직선이 아니라 서로 영향을 주고받으며 고리처럼 이어지는 관계입니다.","r":[]},"융합":{"d":"개인이 가족과 정서적으로 얽혀 자신의 감정과 생각을 구분하지 못하는 상태입니다.","r":["만성불안"]},"만성불안":{"d":"뚜렷한 계기 없이 오래 지속되는 불안으로 보웬 이론에서 미분화된 가족에게 높다고 봅니다.","r":["융합","감정반사행동"]},"감정반사행동":{"d":"불안이 높을 때 생각 없이 감정에 따라 즉각 나오는 습관적 반응입니다.","r":["만성불안"]},"정서적 단절":{"d":"불안을 다루려고 가족과의 감정적 교류를 끊거나 거리를 두는 것입니다.","r":[]},"자아분화":{"d":"감정과 사고를 구분하고 가족으로부터 정서적으로 독립하는 정도로 보웬 이론의 핵심입니다.","r":["융합"]},"핵가족 정서체계":{"d":"부부와 자녀로 이루어진 핵가족 안에서 정서가 오가는 반복적인 방식입니다.","r":[]},"균형깨기":{"d":"가족 내 고정된 균형을 흔들기 위해 치료자가 일부러 한 쪽 편을 드는 구조적 가족치료의 기법입니다.","r":[]},"순환질문":{"d":"가족 구성원들이 서로의 관계와 행동을 어떻게 보는지 번갈아 묻는 밀란 모델의 질문입니다.","r":[]},"원가족 삼인군":{"d":"사티어가 말한 한 사람이 어린 시절 자란 가정의 아버지, 어머니, 자신의 삼각 구도입니다.","r":[]},"합류":{"d":"상담자가 가족의 규칙과 방식에 맞추어 가족체계의 일원처럼 받아들여지는 과정입니다.","r":[]},"가족조각":{"d":"가족 구성원의 자세와 거리로 관계를 몸으로 표현해 보이는 경험적 기법입니다.","r":[]},"생명존중서약":{"d":"자해나 자살 시도를 하지 않겠다는 약속을 상담자와 문서나 말로 맺는 것입니다.","r":[]},"동반의존자":{"d":"중독자에게 정서적으로 매여 그의 문제에 휘말리고 통제하려는 가족이나 주변 사람입니다.","r":[]},"애도작업":{"d":"사랑하는 사람을 잃은 슬픔을 충분히 느끼고 표현하여 상실을 받아들이게 하는 과정입니다.","r":[]},"분열된 충성심":{"d":"자녀가 갈등 중인 부모 양쪽에 모두 충성해야 한다고 느껴 마음이 찢어지는 상태입니다.","r":[]},"가부장적 담론":{"d":"남성이 가족과 사회를 이끌어야 한다는 권력 관계를 당연하게 여기는 사회적 이야기입니다.","r":[]},"선호된 이야기":{"d":"내담자가 자신에게 중요한 가치에 따라 살고 싶어 하는 삶의 이야기입니다.","r":["대안적 정체성"]},"대안적 정체성":{"d":"문제로 규정된 기존 이야기 대신 내담자의 가치를 담아 새로 구축하는 자기 모습입니다.","r":["선호된 이야기"]},"구심성":{"d":"비버즈 모델에서 가족이 안으로 모여 결속하려는 경향입니다.","r":["원심성"]},"원심성":{"d":"비버즈 모델에서 가족 구성원이 밖으로 흩어져 독립하려는 경향입니다.","r":["구심성"]},"연결문":{"d":"해결중심치료의 피드백 메시지에서 칭찬과 과제를 이어 주는 설명 부분입니다.","r":[]}},"notes":{"J의 부모에 대한 분열된 충성심을 다룬다":"갈라선 부모 사이에서 한쪽을 택하면 다른 쪽을 배신하는 것 같은 갈등을 풉니다.","Mental Research Institute":"MRI 모델의 약자가 가리키는 연구소 이름으로, 정신연구소를 뜻하는 영어 표기입니다.","Y가 상담에 자발적으로 참여하였는지 확인한다":"내담자가 스스로 원해서 왔는지 아니면 떠밀려 왔는지를 파악합니다.","Y에 대해 할머니와 부모의 양육태도에서 갈등은 없는지 살핀다":"조부모와 부모가 아이를 다루는 방식이 서로 다른지 확인합니다.","가계도를 활용하여 가족의 정서적 역동과 패턴을 살펴본다":"가계도에 기호로 나타낸 관계를 보면서 가족이 반복하는 정서 패턴을 읽습니다.","가정폭력을 해결하기 위해서는 가족원간의 역기능적 상호작용 패턴과 관계구조를 변화시키는 것이 필요하다":"폭력으로 이어지는 반복적인 상호작용과 관계 구조를 바꾸어야 폭력이 멈춥니다.","가족구성원 간 상호작용을 지지하고 가족체계에 합류한다":"가족이 소통하는 방식을 존중하며 체계 안으로 들어가 신뢰를 얻는 접근입니다.","가족구성원 간의 상호 관계성에 주목한다":"가족 구성원이 서로 연결되어 영향을 주고받는 관계를 중심에 둡니다.","가족구성원 간 행위의 연쇄적인 패턴을 파악하고자 한다":"누가 어떤 행동을 하면 다음에 누가 어떻게 반응하는지 이어지는 흐름을 찾아냅니다.","가족구성원 개인의 내적 경험을 이해하기 위해 빙산기법을 활용한다":"행동 아래에 감춰진 감정과 기대를 층층이 드러내는 사정 도구입니다.","가족구성원의 상호작용 방식을 조직화하는 보이지 않는 요구가 가족구조를 만든다":"구성원이 서로에게 기대하는 눈에 보이지 않는 요구들이 쌓여 가족구조가 형성됩니다.","가족구성원의 정서적 경험과 표현에 중요한 가치를 둔다":"가족이 어떤 감정을 느끼고 어떻게 표현하는지를 치료의 핵심으로 봅니다.","가족구성원이 이해받고 존중받는 느낌을 갖도록 한다":"각자가 자기 입장을 존중받는다고 느껴야 마음을 열고 상담에 참여합니다.","가족 내 학대나 폭력 문제가 있는지 확인한다":"가족 상담을 진행하기 전에 안전을 위협하는 폭력이 있는지 먼저 점검합니다.","가족들에게 상담 참여의 필요성과 과정을 설명한다":"왜 가족이 함께 와야 하는지와 진행 방식을 알려 주어 협조를 구합니다.","가족들이 상담에 오기를 두려워할 때, 참여 독려전화를 하면 불참률을 낮출 수 있다":"가족이 부담을 느낄 때는 미리 전화로 격려하면 상담에 나오는 비율이 올라갑니다.","가족상담에 참여한 모두가 동등하게 이야기하고 상호수용 가능한 의사결정을 내릴 수 있도록 힘의 균형을 유지한다":"한 사람이 대화를 독점하지 않도록 조절해 모두가 말하고 합의한 결정을 내리게 합니다.","가족상담자는 가족이 참여할 수 있도록 격려한다":"말수가 적은 구성원도 참여하도록 북돋워 모든 가족이 상담에 함께하게 합니다.","가족생활주기의 각 단계마다 수행해야 할 과업을 제시한다":"가족이 결혼에서 노년까지 단계를 지나면서 마주하는 발달 과제를 단계별로 정리합니다.","가족생활주기의 결혼전기 단계에서 원가족과 분화가 필요하다고 했다":"결혼 전 단계에서 부모 가정에서 정서적으로 독립하는 것이 과제라고 했습니다.","가족원에게서 느끼는 소외와 외로움으로 인해 다른 대상에 의존":"가족 안에서 소외를 느낀 사람이 정서적 위안을 다른 곳에서 찾으려 의존하게 됩니다.","가족원에게서 느끼는 소외와 외로움으로 인해 다른 대상에 의존함으로써 중독에 이를 수 있다":"가족에게서 채우지 못한 정서적 결핍을 약물이나 행위로 메우다 중독에 빠질 수 있습니다.","가족을 둘러싼 경계가 유동적이나 외부의 영향이 스며들지 않는 것을 말한다":"가족 경계가 고무처럼 늘어나도 바깥의 새로운 생각이나 영향은 받아들이지 않는 상태입니다.","가족의 부적절하고 역기능적인 위계구조를 살펴본다":"자녀가 부모 위에 서거나 권한이 뒤섞인 구조인지 확인합니다.","가족의 비생산적 관계과정을 변화시키기 위해 관계실험을 한다":"기존 관계 패턴을 일부러 다르게 시도해 보면서 불필요한 반복을 끊는 과제를 줍니다.","가족의 의사소통에 초점을 두고 전략적으로 접근한다":"구성원이 문제를 풀려고 반복하는 소통 방식에 주목해 계획적으로 개입합니다.","가족의 정서과정과 생활주기 및 가족원의 증상 등을 파악할 수 있다":"여러 세대의 가족 구성과 관계를 도표로 그려 정서의 흐름과 증상을 한눈에 봅니다.","가족의 폭력문제를 가족원의 낮은 자아분화 수준과 관련 있는 것으로 본다":"보웬은 감정에 휩쓸려 사고하지 못하는 낮은 분화 수준이 폭력의 배경이 된다고 봅니다.","가족이 감정적으로 한 덩어리가 되어 정서적으로 함께 고착되어 있는 상태를 말한다":"구성원이 서로 감정에 얽혀 개별성을 잃고 하나의 덩어리처럼 움직이는 상태입니다.","가족조각을 활용하여 가족원간의 의사소통 체계를 탐색한다":"가족을 몸의 위치와 거리로 표현해 보게 하여 누가 누구와 어떻게 소통하는지 드러냅니다.","개인 및 가족의 심리 내적 경험을 이해할 수 있는 지도이다":"빙산은 겉으로 드러난 행동 아래의 감정과 기대와 열망을 단계별로 보여 줍니다.","개인을 둘러싸고 있는 관계 속에서 일어나는 문제에 더 많은 관심을 가지고 있다":"문제를 개인 내부가 아니라 그 사람이 속한 관계망에서 일어나는 일로 이해합니다.","개인의 삶은 언어를 통한 이야기로 구성되고 창출된다":"삶이 이야기로 엮이고 만들어진다는 뜻이며 이야기를 바꾸면 삶의 의미도 바뀝니다.","개인의 폭력문제도 가족문제 중의 하나로 보고 가족체계에 초점을 두고 접근한다":"폭력을 가해자 한 사람의 문제로 한정하지 않고 가족 관계 속의 문제로 이해합니다.","개인이 불안을 관리하기 위해 가족구성원과 감정적 교류를 더 이상 하지 않는 것이다":"불안을 줄이려고 가족과 접촉을 끊거나 거리를 두는 것이지만 문제가 해결되지는 않습니다.","겉으로 드러난 가족원간의 친밀한 상호작용이 사실과 다른 모습이다":"서로 사이가 좋아 보이지만 진짜 정서적 교류는 없는 가장된 친밀함을 가리킵니다.","게임규칙에 초점을 두고 순환질문을 사용한다":"밀란 모델은 가족이 암묵적으로 따르는 규칙을 드러내려고 서로의 관계를 번갈아 묻습니다.","결혼, 출산, 자녀 성장, 사망 등 구성원의 증가 또는 감소를 축으로 하여 8단계로 나누었다":"듀발은 가족 수가 늘고 줄어드는 사건을 기준으로 가족생활주기를 여덟 단계로 구분했습니다.","결혼생활 중인 부모는 부부관계의 재적응과 재협상에도 주력한다":"자녀 양육 시기에도 부부 사이의 역할과 관계를 다시 맞추고 협의하는 일에 힘써야 합니다.","경험적 가족상담에서는 개인적 차원에서 체계를 다룬다":"가족 전체보다 구성원 한 사람 한 사람의 경험과 성장을 통해 체계를 바꾸려 합니다.","고된 체험, 위장 기법 등의 역설적인 방법을 활용한다":"헤일리는 일부러 증상을 더 힘들게 하게 하거나 반대로 지시해 증상을 포기하게 만듭니다.","과대기능하는 모와 과소기능하는 아들 간 위계 조정을 위해 아들 편을 들면서 균형깨기를 한다":"어머니가 지나치게 나서고 아들이 물러선 구도를 바꾸려고 치료자가 아들 편에 서서 균형을 흔듭니다.","관계 양상을 구심성과 원심성, 혼합형으로 분류한다":"가족이 안으로 모이는지 밖으로 흩어지는지, 두 경향이 섞이는지로 유형을 나눕니다.","구체적이고 측정할 수 있는 행동을 목표로 삼는다":"달성했는지 알 수 있도록 횟수나 빈도로 잴 수 있는 행동을 목표로 합니다.","구체적이고 행동적인 것을 목표로 한다":"막연한 바람이 아니라 눈으로 확인되는 행동으로 목표를 표현합니다.","구체적인 상담 목표를 설정한다":"가족과 함께 달성할 변화를 분명하게 정하여 상담의 방향을 잡습니다.","그 누구도 객관적인 실재를 알 수 없다고 본다":"모든 이해는 관점을 거친 것이므로 관점과 무관한 객관적 현실을 알 수 없습니다.","내담자가 스스로 의사결정을 할 권리를 존중한다":"상담자가 결정을 대신하지 않고 내담자가 스스로 선택하도록 돕습니다.","내담자가 스스로 중요하게 여기는 가치와 의미에 기반한 선호된 이야기를 발견하도록 돕는다":"문제 중심 이야기에 가려진 내담자의 가치를 끌어내 살고 싶은 이야기를 찾게 합니다.","내담자가 어려움과 위기를 어떻게 극복하고 생존해 왔는지 그리고 희망을 버리지 않고 유지해 올 수 있었는지에 관하여 질문하는 동시에 생존능력을 인정하고 간접적으로 칭찬하는 기법이다":"힘든 상황을 어떻게 견뎌 왔는지 물으면서 내담자의 대처 능력을 간접적으로 인정해 줍니다.","내담자가 중요하다고 여기는 것을 목표로 한다":"상담자가 아닌 내담자에게 의미 있는 것이어야 변화하려는 동기가 생깁니다.","내담자에게 상담사의 가치를 강요하지 않는다":"상담자 개인의 가치관을 내담자에게 따르게 하지 않고 내담자의 선택을 존중합니다.","내담자의 강점과 자원은 물론 증상까지도 상담에 활용한다":"강점뿐 아니라 증상에서도 해결에 쓸 단서를 찾아 활용합니다.","대표 인물로 사티어(V. Satir)와":"경험적 가족상담의 대표 학자로 사티어를 꼽는다는 문장의 앞부분입니다.","두 가지 모순된 메시지가 서로 다른 수준에서 전달되는 경우이다":"말로는 한 가지를 전하고 태도로는 반대를 전해서 받는 사람이 어느 쪽에도 따를 수 없게 됩니다.","두 사람 사이의 불안과 긴장을 해소하기 위하여 다른 사람이나 대상을 관계로 끌어들이는 것이다":"둘 사이의 긴장을 제삼자를 끌어들여 낮추려는 방식으로 세 사람의 관계가 형성됩니다.","따뜻함과 직면을 균형적으로 사용한다":"상담자는 가족에게 따뜻하게 다가가면서도 필요할 때는 문제를 마주 보게 합니다.","마지막 단계는 대안적 정체성을 구축하는 것이다":"문제로 규정된 자기상을 벗어나 새롭게 선택한 정체성을 세우며 치료를 마무리합니다.","만성불안에 대한 감정반사행동을 줄이는 것을 목표로 한다":"불안할 때 자동으로 튀어나오는 반응을 줄이고 생각해서 대응하게 하는 것이 치료의 목표입니다.","만성불안의 수준이 높고 융합의 정도가 높다":"분화 수준이 낮은 사람은 불안이 늘 높고 가족과 정서적으로 얽혀 있는 정도가 큽니다.","목표 수행은 힘든 일이라는 것을 내담자가 인식하도록 한다":"목표 달성이 쉽지 않음을 미리 알아야 어려움을 겪어도 쉽게 포기하지 않습니다.","목표 수행이 힘들고 어려운 일이라고 인식하게 한다":"변화에는 노력이 따른다는 현실을 인식시켜 기대를 현실적으로 맞춥니다.","문제해결, 의사소통, 역할, 정서적 반응, 상호작용, 행동통제, 일반적 기능 등으로 평가한다":"기능하는 여러 측면을 항목별로 나누어 평가하는 맥매스터 모델의 방식입니다.","변화는 삶의 일부로서 불가피하며 계속적으로 일어난다고 가정한다":"변화가 늘 일어나고 있으므로 이미 나타난 긍정적 변화를 찾아 키울 수 있다고 봅니다.","본질적인 진실이란 존재하지 않는다는 관점을 가진다":"모든 사람에게 변함없이 적용되는 진리는 없고 진실은 맥락에 따라 달라집니다.","부모-자녀하위체계가 적절한 기능을 하는지 살펴본다":"부모가 자녀를 지도하고 자녀가 따르는 관계가 알맞게 작동하는지 확인합니다.","부모가 권위와 책임을 바탕으로 세대 간 차이를 인정하는 구조이다":"부모가 자녀보다 위의 위치에서 책임을 지고 세대 구분이 분명한 건강한 위계입니다.","부모가 서로 지원하고 서로에게 적응함으로써 자녀에게 일관된 모습을 보여야 한다":"부모가 서로 맞춰 일치된 태도를 보이면 자녀가 혼란 없이 규칙을 따를 수 있습니다.","부모가 자신들의 미성숙함을 자녀에게 투사하는 과정이다":"부모가 자기 불안과 문제를 자녀에게 옮겨 자녀를 문제 있는 존재로 대하게 됩니다.","부모는 자녀끼리 협상하고 갈등이나 차이를 해결하도록 지원한다":"형제 사이의 다툼에 부모가 대신 판결하지 않고 스스로 풀 수 있게 돕습니다.","부모의 미숙함에 노출되는 자녀":"분화 수준이 낮은 가족에서 부모의 미성숙한 면에 영향을 받게 되는 자녀를 가리킵니다.","부모 하위체계와 별도로 부부 하위체계가 기능하도록 한다":"부모 역할과 별개로 부부 둘만의 관계를 유지하는 영역이 필요합니다.","부부관계를 파악하고 원가족을 이해하는 데 도움을 준다":"부부가 자신의 관계와 각자 자란 가정을 이해하게 돕는 검사입니다.","사생활과 비밀보장의 원칙과 예외상황을 알린다":"상담 내용은 비밀이지만 위험이 있을 때처럼 예외가 있다는 점을 처음에 알려 줍니다.","사적인 친밀관계, 성적 관계, 동업자관계 등의 관계를 맺지 않는다":"상담 관계 밖의 다른 관계를 맺으면 객관성이 흐려지고 내담자에게 해가 될 수 있습니다.","삶의 이야기 속에는 사회적 담론과 자기정체성이 포함된다":"이야기에 사회가 당연시하는 생각들과 자신을 규정하는 방식이 함께 담겨 있습니다.","상담에 참석해야 할 사람과 날짜, 장소, 시간을 구체적으로 정한다":"첫 면담에서 누가 언제 어디서 오는지 분명히 정해 두어야 빠지는 사람이 없습니다.","상담을 시작하기 전에 내담자에게 자신의 권리와 책임에 대해 충분히 설명한 후 동의를 구해야 한다":"내담자가 상담에서 가지는 권리와 의무를 알게 한 뒤 동의를 받는 것이 순서입니다.","상담자는 내담자와 사적인 친밀관계, 성적관계, 동업자관계 등을 피해야 한다":"이중관계는 내담자를 이용하거나 판단을 흐리게 하므로 윤리적으로 금지됩니다.","상담자 역할의 범위와 가족의 행동규범에 관해 안내한다":"상담자가 할 수 있는 일과 상담 중 지켜야 할 규칙을 미리 밝혀 줍니다.","상징-경험적 가족상담자들은 내담자들과의 관계 구축을 위해":"가족상담자가 내담자와 관계를 맺기 위해 어떻게 하는지 설명하는 문장의 앞부분입니다.","상징-경험적 상담의 휘태커는 정서적 과정과 가족구조에 초점을 맞춘다":"휘태커는 가족이 느끼는 감정의 흐름과 가족의 구조를 함께 다룹니다.","세계와 인간경험은 개인이 해석하는 방식으로 존재한다":"세계는 해석되는 방식에 따라 그 모습으로 경험된다는 관점입니다.","순환적 인과관계를 통해 문제를 이해하고자 한다":"한 사람이 원인이라고 지목하지 않고 서로 영향을 주고받는 고리로 문제를 설명합니다.","순환적 인과관계 속에서 증상을 이해하려고 한다":"증상을 한 개인의 결함이 아니라 가족의 상호작용 순환 속에서 나타난 것으로 이해합니다.","실재(reality)는 언어를 통해 구성된다고 본다":"객관적으로 존재하는 현실이 아니라 언어로 만들어진 의미 체계가 곧 현실입니다.","실재는 상호작용을 통해 사회적으로 구성된다고 본다":"사람들이 서로 주고받는 과정에서 현실의 의미가 합의되고 만들어집니다.","심한 수치심을 느끼고 자존감 형성에 부정적 영향을 받는다":"집안의 폭력을 부끄러워하면서 자신에 대한 긍정적인 평가를 키우기 어렵습니다.","아버지와의 친밀감 향상을 위한 작업을 한다":"소원해진 부자 관계를 가깝게 하는 데 목표를 둡니다.","알코올 문제가 이어지고 있다":"가계도에서 환자의 할아버지와 아버지에게 알코올 문제가 대를 이어 나타난다는 내용입니다.","애정과 돌봄 역할에 관심을 두고 치료 작업을 한다":"마다네스는 가족 내 사랑과 보호 같은 돌봄의 구도를 중심으로 치료합니다.","어머니와의 정서적 단절 이슈에 대해 작업한다":"어머니와 감정적 교류를 끊고 지내는 문제를 상담의 주제로 삼습니다.","어머니와의 친밀감 향상 등 관계 회복을 위한 작업을 한다":"멀어진 어머니와 아들의 정서적 거리를 좁히는 과제를 합니다.","언제 폭력이 발생할지, 자신이 폭력을 촉발시키지는 않을지 불안해하고 두려움을 느낀다":"예측할 수 없는 폭력과 자신이 원인이 될지 모른다는 생각 때문에 늘 불안합니다.","완벽한 분화는 집단 안에서 한 개인이 된다는 것이다":"가족과 정서적으로 연결되어 있으면서도 자기 생각과 감정을 지닌 독립된 사람이 되는 것입니다.","요소는 자기, 타인, 상황으로 낮은 자아존중감을 회복시키는 것이 목표이다":"사티어는 자기와 타인과 상황을 모두 존중하는 일치형 소통으로 낮은 자아존중감을 높이려 합니다.","우리가 살아가는 실재는 언어를 통해 구성되고 표현된다":"우리가 경험하는 현실은 언어로 해석하고 말하는 과정을 거쳐 만들어집니다.","우리가 살아가는 이야기는 사회적 맥락 속에서 만들어진다":"삶의 이야기에는 주변 사회가 건네는 의미들이 스며 있습니다.","원래 트라우마와 학대 생존자들을 위한 치료로":"내면가족체계치료가 처음에 외상과 학대에서 살아남은 사람들을 위해 개발됐다는 설명의 앞부분입니다.","위태커(C. Whitaker)가 있다":"사티어와 함께 경험적 가족상담을 대표하는 인물로 휘태커가 있습니다.","이야기는 사회적 맥락 속에서 만들어진다고 본다":"개인의 이야기는 혼자 만든 것이 아니라 사회와 문화가 주는 영향 속에서 짜입니다.","이야기치료는 발달 초기에 베이트슨의 영향을 받았다":"이야기치료는 초기에 체계 이론가 베이트슨의 사고에서 영향을 받으며 시작되었습니다.","인간은 사회적 관계와 문화적 맥락 속에서 자신을 이해하고 정체성을 형성해 간다":"자기 정체성은 타인과 문화와의 관계를 통해 만들어진다는 전제입니다.","인간은 자신에게 일어나는 삶의 사건을 해석하고 그에 대해 의미를 부여한다":"사건 자체보다 그것을 어떻게 해석하고 의미를 두는지가 경험을 결정합니다.","인본주의 심리학에 뿌리를 두고 있다":"인간이 성장하려는 힘을 믿는 인본주의 심리학을 이론적 바탕으로 삼습니다.","인종, 성별, 출신국가 등에 관계없이 내담자를 공정하게 대우해야 한다":"내담자의 속성을 이유로 차별하지 않고 누구에게나 같은 수준으로 서비스를 제공합니다.","일종의 명령으로 원가족 삼인군의 경험에서 획득하여 내재화한 것이다":"어린 시절 부모와 자신으로 이루어진 관계에서 받아들인 지침이 마음속 명령으로 남은 것입니다.","자녀가 가족체계에 자유롭게 출입할 수 있도록 가족의 경계를 유연하게 설정한다":"청소년 자녀가 가족 안팎을 오갈 수 있게 경계를 지나치게 닫지 않아야 합니다.","자녀가 책임감을 가지도록 가족의 구조와 조직을 변화시킨다":"자녀에게 맡기는 몫을 늘리는 방향으로 가족의 구조와 운영을 조정합니다.","자녀 양육기의 가족은 부모와 자녀를 분리하여 부부생활과 자녀양육 생활을 독립적으로 하도록 했다":"양육기에는 부부 영역과 자녀 영역을 나누어 각각 따로 운영하도록 했다는 설명입니다.","자녀의 발달과 변화에 대응하여 부모의 역할도 변해야 한다":"자녀가 자라면 요구가 달라지므로 부모도 보호자에서 안내자로 역할을 바꿔야 합니다.","자녀의 발달단계에 맞는 규칙을 설정하고 부모의 권위를 적절히 사용해야 한다":"자녀 나이에 알맞은 규칙을 정하고 필요한 만큼 권위를 행사하는 것이 부모체계의 기능입니다.","자해의 강도, 빈도 등을 확인하고 생명존중서약을 받는다":"자해의 정도를 파악하고 더는 자신을 해치지 않겠다는 약속을 받아 안전을 확보합니다.","중독가정에서 중독자에게 의존되어 있는 사람을 동반의존자라고 한다":"동반의존자는 중독자를 돌보고 통제하는 일에 얽매여 자신의 삶을 잃은 가족이나 주변 사람입니다.","중독문제는 가족의 부정적 상호작용 패턴에 의해 유지된다고 본다":"되풀이되는 비난이나 감싸기 같은 방식이 중독을 이어 가게 한다는 관점입니다.","중독의 원인을 가족의 체계나 구조에 있다고 전제한다":"가족상담은 중독이 개인 의지 문제가 아니라 가족 체계에서 비롯된 것으로 가정합니다.","중독이 장기화될수록 가정에는 우울과 절망감 등의 부정적인 정서가 심화된다":"중독이 오래 이어지면 가족 모두가 지쳐 우울과 희망 없음이 짙어집니다.","지각과 결석 등 문제가 생길 무렵 가족내에 발생한 문제가 있었는지 확인한다":"행동 문제가 시작된 시기에 가족에게 어떤 변화가 있었는지 연결해 봅니다.","지금-여기에서 일어나는 상호작용 과정을 중시한다":"과거 사건의 분석보다 상담 중인 지금 가족이 주고받는 상호작용을 다룹니다.","지금 여기에서 시작하는 것을 목표로 한다":"먼 미래가 아니라 지금 당장 시작할 수 있는 작은 변화를 목표로 합니다.","첫 면담의 주요 목표는 라포형성과 정보 수집에 있다":"처음에는 가족과 신뢰 관계를 맺고 문제에 대한 기본 정보를 모으는 것이 우선입니다.","청소년 중독자의 경우 가족의 영향력이 강하기 때문에 가족상담적 접근이 필요하다":"청소년은 가족의 영향을 크게 받아 개인 치료만으로는 부족하므로 가족을 함께 다룹니다.","체계가 변화나 이탈을 거부하고 안정성을 유지하는 방향으로의 피드백이다":"변화를 막고 기존 상태로 되돌려 체계를 안정시키는 작용을 합니다.","체계는 일정한 규칙에 의해 유지되고 기능한다":"가족도 구성원 사이의 규칙에 따라 일정한 방식으로 작동하며 유지됩니다.","체계를 구성하는 개인 간 관계에 초점을 두고 개입한다":"개개인보다 그들 사이의 관계 양상을 바꾸는 방향으로 개입합니다.","체계적 원리를 이용하여 개인의 내적인 부분들과 작업한다":"가족을 다루는 체계 원리를 개인의 마음속 여러 부분에 적용해 치료합니다.","출생순위 또는 형제자매 위치가 가족의 정서체계 안에서 특정한 역할과 기능을 한다":"맏이인지 막내인지에 따라 가족 안에서 맡는 역할과 성향이 달라진다는 개념입니다.","치료적 피드백 메시지는 칭찬, 연결문, 과제의 세 부분으로 구성되어 있다":"상담 끝에 전하는 메시지는 칭찬으로 시작해 연결문을 거쳐 과제로 이어집니다.","친할머니의 상실에 대한 애도작업을 한다":"친할머니를 잃은 슬픔이 정리되지 않았을 때 그 감정을 다룹니다.","침투적이고 모호한 경계선을 가진 가족은 강한 소속감 때문에 자율성이 방해를 받는다":"구성원 사이의 경계가 흐려 지나치게 밀착되면 각자의 독립성이 약해집니다.","탈이론적이고 비규범적이며 내담자의 견해를 존중한다":"정해진 이론이나 기준으로 판단하지 않고 내담자가 세상을 보는 방식을 존중합니다.","포스트모더니즘과 사회구성주의적인 시각에 근거한다":"절대적 진리를 인정하지 않고 지식이 사회적으로 만들어진다고 보는 철학적 흐름에 바탕을 둡니다.","폭력, 가출, 비행, 자살시도 등 심각한 부적응 행동을 표출할 가능성이 높아진다":"폭력을 목격한 자녀는 이를 행동으로 옮기거나 집을 떠나거나 스스로를 해치는 문제를 겪기 쉽습니다.","폭력에 기여하는 가부장적 담론을 파악하고 해체하여 대안적 이야기를 구축한다":"폭력을 정당화하는 사회적 생각의 틀을 드러내 무너뜨리고 새 이야기를 만듭니다.","폭력을 행하는 부모뿐 아니라 폭력을 제지할 수 없는 자신의 무력함에도 분노를 느낀다":"가해 부모에 대한 분노에 더해 아무것도 못 한 자신에 대한 화도 함께 품습니다.","학교 폭력과 가정 폭력이 있었는지 확인한다":"청소년의 문제 행동 배경에 폭력 피해나 목격이 있었는지 알아봅니다.","할아버지 상실에 대한 애도작업을 한다":"가족이 할아버지의 죽음을 충분히 슬퍼하지 못했다면 그 상실을 다루어 중독의 배경을 풉니다.","핵가족 내에서 가족이 정서적으로 기능하는 패턴을 말한다":"부부와 자녀가 정서 문제를 처리하는 반복적인 방식으로 갈등과 거리두기 등이 있습니다.","핵가족 정서체계에서 부모의 부부관계를 다룬다":"부모 사이의 갈등이 자녀에게 영향을 주므로 부부 관계를 다룹니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
